/* Vendor (level 0) update: walks a path, turns toward the player, attacks and self-destructs.
   Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/l00/gameplay_vendor_002e0988.c, FUN_L00_002e0b88. */
extern Hero hero __asm__("D_0013F450");

void veldin_robot_enemy_update(Moby *moby) {
    enum {
        VELDIN_ROBOT_STATE_INITIALIZE = 0,
        VELDIN_ROBOT_STATE_WAIT_TO_FOLLOW_PATH = 1,
        VELDIN_ROBOT_STATE_FOLLOW_PATH = 2,
        VELDIN_ROBOT_STATE_FACE_TARGET = 3,
        VELDIN_ROBOT_STATE_WAIT_TO_START_COLLISION_PROBES = 4,
        VELDIN_ROBOT_STATE_PROCESS_COLLISION_PROBES = 5,
        VELDIN_ROBOT_STATE_WAIT_TO_RETURN_TO_FACE_TARGET = 6,
        VELDIN_ROBOT_STATE_DAMAGE_KNOCKBACK = 7,
        VELDIN_ROBOT_STATE_DEATH_KNOCKBACK = 8
    };
    VendVars *vars;
    VendTarget *target;
    VendPath *path;
    Vec4 delta;
    Vec4 dir;
    Vec4 mtx[4];
    VendQuery query;
    Vec4 probe;
    f32 vel;
    s32 hit;

    vars = (VendVars *)moby->pvars;
    update_veldin_robot_damage_and_targeting(moby);
    target = vars->target;
    manipulator_set_scale(vars->unk120, 2.5f);
    if (draw_map51_m[3] != 0) {
        EaseManipulatorOffsets((char *)moby, (char *)vars->unk120, 2, *(float *)&g_frame_scale_sq_s * 0.03f, *(float *)&g_frame_scale_sq_s * 0.3f);
    }
    if (moby->visible != 0 && FastVecDist(&moby->pos, g_debug_camera) < 27.0f) {
        set_ground_height_band(moby);
        moby->shadow_range = 0x15;
    }
    switch (moby->state) {
    case VELDIN_ROBOT_STATE_INITIALIZE:
        qcopy(&vars->spawnPos, &moby->pos);
        vars->unk29 = 0;
        vars->unk20 = 2.0f;
        vars->unk28 = 1;
        vars->unk24 = 2;
        vars->unk58 = truncate_float_to_s32_r(14.0f);
        vars->unk5A = truncate_float_to_s32_r(8.0f);
        vars->pathPt = 1;
        if (random_integer_below(2) != 0) {
            moby->flags |= 0x8000;
        }
        if (vars->pathIdx >= 0) {
            if (vars->unk1B4 == -1) {
                DeleteMoby(moby);
                return;
            }
            qcopy(&moby->pos, &level_paths[vars->pathIdx]->pts[0]);
            moby->state = VELDIN_ROBOT_STATE_WAIT_TO_FOLLOW_PATH;
            if (moby->prev_seq != 1) MobyBlendAnimation(moby, 1, 0, 5);
        } else {
            moby->state = VELDIN_ROBOT_STATE_FACE_TARGET;
            if (moby->prev_seq != 1) MobyBlendAnimation(moby, 1, 0, 5);
        }
        break;
    case VELDIN_ROBOT_STATE_WAIT_TO_FOLLOW_PATH:
        if (moby->anim_flags & 2) {
            if (moby->prev_seq == 1 && random_integer_below(4) == 0) {
                if (moby->prev_seq != 2) MobyBlendAnimation(moby, 2, 0, scale_ticks(20));
            } else {
                if (moby->prev_seq != 1) MobyBlendAnimation(moby, 1, 0, scale_ticks(20));
            }
        }
        if (vars->unk114 != 2) {
            moby->state = VELDIN_ROBOT_STATE_FOLLOW_PATH;
            if (moby->prev_seq != 9) MobyBlendAnimation(moby, 9, 0, scale_ticks(10));
        }
        break;
    case VELDIN_ROBOT_STATE_FOLLOW_PATH:
        vel = 0.0f;
        path = level_paths[vars->pathIdx];
        qcopy(&delta, &path->pts[vars->pathPt]);
        SteerAngleWithVelocity(&moby->rot.z, fast_atan2(delta.f[0] - moby->pos.x, delta.f[1] - moby->pos.y), &vars->turnVel, g_frame_time_sq * (12.566371f), g_frame_time_sq * (12.566371f), g_frame_time * 12.566371f);
        FastVecSub(&dir, &delta, &moby->pos);
        ApproachWithVelocity(FastVecDist(&moby->pos, &path->pts[path->count - 1]), g_frame_time_sq * 8.0f, g_frame_time_sq * 16.0f, g_frame_time * 12.0f, &vel, &vars->speed);
        if (FastVecLength(&dir) < vars->speed + vars->speed) {
            vars->pathPt++;
            if (vars->pathPt == path->count) {
                moby->state = VELDIN_ROBOT_STATE_FACE_TARGET;
                if (moby->prev_seq != 1) MobyBlendAnimation(moby, 1, 0, scale_ticks(10));
            }
        }
        vec_scale_to_length(&dir, &dir, vars->speed);
        FastVecAdd(&moby->pos, &moby->pos, &dir);
        break;
    case VELDIN_ROBOT_STATE_FACE_TARGET:
        SteerAngleWithVelocity(&moby->rot.z, fast_atan2(target->pos.f[0] - moby->pos.x, target->pos.f[1] - moby->pos.y), &vars->turnVel, g_frame_time_sq * (12.566371f), g_frame_time_sq * (12.566371f), g_frame_time * 12.566371f);
        if (vec_distance_xy(&moby->pos, &hero.motion.pos) < 20.0f) {
            if (moby->prev_seq != 4) MobyBlendAnimation(moby, 4, 0, scale_ticks(20));
        } else if (moby->anim_flags & 2) {
            if (moby->prev_seq != (random_integer_below(2) + 1)) MobyBlendAnimation(moby, (random_integer_below(2) + 1), 0, scale_ticks(20));
        }
        if (vars->unk114 != 2 && register_beam_slot(moby, 0, 0) != 0) {
            moby->state = VELDIN_ROBOT_STATE_WAIT_TO_START_COLLISION_PROBES;
            if (moby->prev_seq != 5) MobyBlendAnimation(moby, 5, 0, scale_ticks(10));
        }
        break;
    case VELDIN_ROBOT_STATE_WAIT_TO_START_COLLISION_PROBES:
        SteerAngleWithVelocity(&moby->rot.z, fast_atan2(target->pos.f[0] - moby->pos.x, target->pos.f[1] - moby->pos.y), &vars->turnVel, g_frame_time_sq * (12.566371f), g_frame_time_sq * (12.566371f), g_frame_time * 12.566371f);
        if (moby->anim_flags & 2) {
            vars->timer = 0;
            moby->state = VELDIN_ROBOT_STATE_PROCESS_COLLISION_PROBES;
            if (moby->prev_seq != 6) MobyBlendAnimation(moby, 6, 0, scale_ticks(10));
        }
        break;
    case VELDIN_ROBOT_STATE_PROCESS_COLLISION_PROBES: {
        f32 desired_heading;
        s32 lim;

        desired_heading = fast_atan2(vars->homeX - moby->pos.x, vars->homeY - moby->pos.y);
        if (moby->flags & 0x8000) {
            desired_heading = FastAddRots(desired_heading, *(float *)&veldin1_robot_beam_sweep_angle);
        } else {
            desired_heading = FastSubRots(desired_heading, *(float *)&veldin1_robot_beam_sweep_angle);
        }
        SteerAngleWithVelocity(&moby->rot.z, desired_heading, &vars->turnVel, g_frame_time_sq * (1.5707964f), g_frame_time_sq * (1.5707964f), g_frame_time * 12.566371f);
        MobyTransformScaledVertex((char *)moby, 0, (char *)mtx);
        qcopy(&delta, &moby->rot_row0);
        delta.f[2] = 0.0f;
        vec_scale_to_length(&delta, &delta, *(float *)&veldin1_robot_beam_origin_offset);
        FastVecAdd(&dir, &mtx[3], &delta);
        hit = 0;
        query.flags = 0x10000;
        query.moby = moby;
        query.unk90 = 1;
        query.unk8C = 1.0f;
        query.dir[0] = FastCos(moby->rot.z);
        query.dir[1] = FastSin(moby->rot.z);
        query.dir[3] = 5627.925f;
        query.unk89 = 1;
        query.unk8A = (*(u16 *)&moby->oclass);
        query.dir[2] = 1.0f;
        query.unk88 = 0;
        if (moby->seq == moby->prev_seq && MobyGetFrameValue(moby) > 1.0f) {
            hit = 1;
            query.flags |= 1;
        }
        qcopy(&probe, &moby->pos);
        probe.f[2] += 0.5f;
        if (coll_line(&mtx[3], &probe, 0, (int)moby, (int)&query) != 0 && hit != 0 &&
            g_coll_hit_moby.moby == hero.moby) {
            release_beam_slot_by_id(moby);
            moby->state = VELDIN_ROBOT_STATE_WAIT_TO_RETURN_TO_FACE_TARGET;
            if (moby->prev_seq != 7) MobyBlendAnimation(moby, 7, 0, scale_ticks(10));
        }
        if (coll_line(&mtx[3], &dir, 0, (int)moby, (int)&query) != 0) {
            qcopy(&dir, g_coll_hit_moby.pos);
            if (hit != 0 && g_coll_hit_moby.moby == hero.moby) {
                release_beam_slot_by_id(moby);
                moby->state = VELDIN_ROBOT_STATE_WAIT_TO_RETURN_TO_FACE_TARGET;
                if (moby->prev_seq != 7) MobyBlendAnimation(moby, 7, 0, scale_ticks(10));
            }
        }
        set_beam_origin_transform_and_endpoint(moby, mtx, &dir);
        if (moby->anim_flags & 2) {
            lim = *(int *)&veldin1_robot_beam_sweep_cycles;
            if (vars->timer++ == lim) {
                release_beam_slot_by_id(moby);
                moby->state = VELDIN_ROBOT_STATE_WAIT_TO_RETURN_TO_FACE_TARGET;
                if (moby->prev_seq != 12) MobyBlendAnimation(moby, 12, 0, scale_ticks(10));
            }
        }
        break;
    }
    case VELDIN_ROBOT_STATE_WAIT_TO_RETURN_TO_FACE_TARGET:
        SteerAngleWithVelocity(&moby->rot.z, fast_atan2(target->pos.f[0] - moby->pos.x, target->pos.f[1] - moby->pos.y), &vars->turnVel, g_frame_time_sq * (12.566371f), g_frame_time_sq * (12.566371f), g_frame_time * 12.566371f);
        if (moby->anim_flags & 2) {
            moby->state = VELDIN_ROBOT_STATE_FACE_TARGET;
            if (moby->prev_seq != 1) MobyBlendAnimation(moby, 1, 0, scale_ticks(10));
        }
        break;
    case VELDIN_ROBOT_STATE_DAMAGE_KNOCKBACK:
        if (mine_fall(moby, vars->unk70) & 0x140) {
            moby->state = VELDIN_ROBOT_STATE_FACE_TARGET;
            if (moby->prev_seq != 1) MobyBlendAnimation(moby, 1, 0, scale_ticks(10));
        }
        break;
    case VELDIN_ROBOT_STATE_DEATH_KNOCKBACK:
        if (mine_fall(moby, vars->unk70) & 0x140) {
            SpawnExplosionFx(moby, &moby->pos, -1, 0.75f, 13.0f);
            spawn_moby_break_fragments(moby, 0x7AB, 1, 0x7AB, 1, 4, 0);
            SpawnBreakFragment((char *)moby, 0x78D, (float *)((Vec4 *)&moby->pos), &moby->rot, 0, 0, 0.0f, (float *)veldin1_zero_vec, (float *)veldin1_zero_vec, (float *)veldin1_zero_vec);
            SpawnBreakFragment((char *)moby, 0x78E, (float *)((Vec4 *)&moby->pos), &moby->rot, 0, 0, 0.0f, (float *)veldin1_zero_vec, (float *)veldin1_zero_vec, (float *)veldin1_zero_vec);
            SpawnBreakFragment((char *)moby, 0x78F, (float *)((Vec4 *)&moby->pos), &moby->rot, 0, 0, 0.0f, (float *)veldin1_zero_vec, (float *)veldin1_zero_vec, (float *)veldin1_zero_vec);
            DeleteMoby(moby);
            return;
        }
        break;
    }
    update_veldin_robot_effects((char *)moby);
}
