/* Update for the troll moby: takes hits, picks and tracks its target. Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/l00/gameplay_vendor_002e0988.c, FUN_L00_002e1678. */
void update_veldin_robot_damage_and_targeting(void *mv) {
    TrollMoby *m = mv;
    TrollVars *vars;
    void *anim;
    TrollColl *coll;
    VendPath *path;
    TrollMoby *t;
    Vec4 v;
    u8 *g;
    s32 hit;
    f32 dmg;
    f32 angle;
    f32 unused;
    f32 range;
    u8 *pp;

    vars = m->vars;
    if (m->state == 0) {
        return;
    }
    if (vars->unk38 != 0) {
        vars->unk38 = 0;
        vars->unk1DA = scale_ticks(rand_range(0xB4, 0x12C));
    }
    FastDecTimer(&vars->unk1DA);
    anim = vars->unk60;
    dmg = 0.0f;
    coll = (TrollColl *)MobyGetHitMessage(m, 0x330000, 0);
    ComputeHitResponse(m, coll, &vars->health, 0, &hit, &dmg, 0, 4);
    if (hit != 1 && m->state != 8 && dmg != 0.0f) {
        vars->health -= dmg;
        vars->unk90 = 0x200;
        vars->unk80 = veldin1_robot_hit_knock_gravity * g_frame_time_sq;
        vars->unk84 = veldin1_robot_hit_knock_drag * g_frame_time_sq;
        vars->unk88 = veldin1_robot_hit_knock_speed * g_frame_time;
        vars->unk8C = veldin1_robot_hit_knock_lift * g_frame_time;
        vars->unkAD = 0;
        vars->unk94 = 9;
        vars->unkBC = g_frame_time + g_frame_time;
        vars->unk98 = 0.5f;
        if (vars->health <= 0.0f) {
            vars->unk94 = 0x29;
            m->flags &= ~0x1000;
            v.q = coll->pos.q;
            HeadingFromVector(&v, &angle, &vars->unk88, &vars->unk8C);
            InitKnockback(m, vars->unk70, angle, 0xB, 1, 0);
            vars->unkC0 = 7.0f;
            vars->unkC4 = 16.0f;
            m->state = 8;
            m->unk94 = 0;
            vars->unk67 = 0x78;
            RerollEffectCounter(m, anim);
            SetDeathBits(m, 0, -1);
        } else {
            pp = vars->unk70;
            vars->unk88 = veldin1_robot_hit_knock_speed * g_frame_time * 0.35f;
            vars->unk8C = veldin1_robot_hit_knock_lift * g_frame_time * 0.5f;
            v.q = coll->pos.q;
            HeadingFromVector(&v, &unused, &vars->unk88, &vars->unk8C);
            InitKnockback(m, pp, fast_atan2(coll->pos.f[0], coll->pos.f[1]), 8, 1, 0);
            vars->unkC4 = vars->unkC0 = -1.0f;
            m->state = 7;
            vars->unk67 = 0xFA;
            vars->unk26 = scale_ticks(0x3C);
            RerollEffectCounter(m, anim);
        }
        release_beam_slot_by_id(m);
    }
    m->unkA4 = 0xFF;
    StepColorFade(m, anim);
    if (m->state == 1) {
        path = level_paths[vars->unk1B4];
        FindNearestEligibleMoby(64.0f, (char *)m, &vars->target, 0, 0, path->pts, path->count);
    } else if (m->state != 5) {
        range = veldin1_robot_target_range;
        if (vars->unk1DA != 0) {
            range = 37.0f;
        }
        if (FindNearestTargetMoby(m, range, &vars->target) != 2 && range < vec_distance_xy(&m->pos, &vars->target)) {
            vars->unk114 = 2;
        }
    }
    if (vars->targetMoby == 0) {
        g = hero_globals_base + 0xE1D;
        vars->targetMoby = *(TrollMoby **)(g + 0x2080);
        qcopy(&vars->target, g + 0x80);
    }
    if (vars->unk1BC >= 0) {
        t = (TrollMoby *)(moby_array_start + (vars->unk1BC << 8));
        if (t == 0 || t->state == 0xFE || t->state == 0xFD) {
            vars->unk1BC = -1;
        } else {
            range = vec_distance_xy(&m->pos, &t->pos);
            if (range < vec_distance_xy(&m->pos, &vars->targetMoby->pos)) {
                vars->targetMoby = t;
                qcopy(&vars->target, &t->pos);
                vars->unk114 = 1;
            }
        }
    }
}
