typedef float W[4] __attribute__((aligned(16)));
typedef struct {
    int c[4];
    int z0, z1, z2;
    float f0, f1;
    int z3;
    float f2, f3;
    long z4, q0, q1, q2;
} T;

/* Builds a four-vertex quad facing the camera from the moby's data point and runs the draw packet. */
void draw_veldin_robot_effect_quad(char *m) {
    W q[4];
    T t;
    W c, d, e, bb;
    float (*p)[4];
    float *qq;
    int i;
    qcopy(bb, ((char *)((Moby *)m)->pvars) + 0x1C0);
    bb[3] = 1.0f;
    FastVecSub(c, g_debug_camera, bb);
    vec_scale_to_length(c, c, 1.0f);
    FastVecCross(d, c, hero_globals_base + 0x10AD);
    vec_scale_to_length(d, d, -1.0f);
    FastVecCross(e, d, c);
    t.q0 = GetEffectTex(11);
    t.q2 = 0x8000000048L;
    t.q1 = 0xFF9000000260L;
    t.z4 = 5;
    t.c[3] = 0x80FFFFFF;
    t.c[2] = 0x80FFFFFF;
    t.c[1] = 0x80FFFFFF;
    t.c[0] = 0x80FFFFFF;
    t.z0 = 0;
    t.z1 = 0;
    t.z2 = 0;
    t.f0 = 1.0f;
    t.f1 = 1.0f;
    t.z3 = 0;
    t.f2 = 1.0f;
    t.f3 = 1.0f;
    p = veldin1_robot_effect_quad_corners;
    qq = q[0];
    for (i = 3; i >= 0; i--) {
        FastVecScale(qq, p, 0.2f);
        p++;
        qq += 4;
    }
    draw_world_quad(q, c, 0);
}
