/* Cutscene effect controller: switch camera targets and spawn a smoke trail at a joint. */
void update_phase_effect_controller(M2 *m) {
    char buf[16];
    int idx;
    int i, col, h;
    char *p, *q, *r;
    
    switch (m->state) {
    case 0:
        m->v = 0xFF;
        m->state = 1;
        break;
    case 1:
        if (cinematic_mode == 2) {
            if ((cutscene_state.a == 2 && cutscene_state.b >= scale_ticks(0x618)) || (cinematic_mode == 2 && cutscene_state.a == 3)) {
                idx = -1; if (cutscene_state.a == 2) idx = 3; else if (cutscene_state.a == 3) idx = 2;
                cutscene_set_camera_target(cutscene_state.arr[idx]);
            }
            if (cinematic_mode == 2) {
                if (cutscene_state.a == 4) {
                    p = (char *)cutscene_state.arr[3];
                    if (p == 0) return;
                    if (cutscene_state.b < scale_ticks(0x96)) return;
                    if (scale_ticks(0xDC) < cutscene_state.b) return;
                    Moby_GetJointWorldPos(p, 0, buf);
                    draw_trail(buf, buf, veldin1_zero_vec, 120000.0f, 50000.0f);
                    for (i = 0; i < 10; i++) {
                        col = (rand_range(0x40, 0x80) << 24) | 0x787878;
                        h = rand_range(0, 4);
                        if (random_integer_below(2)) h = -h;
                        q = PartType23Spawn(buf, h, veldin1_zero_vec_b, col, 0.75f, 1.0f, 1.03f, 120000.0f);
                        if (q) {
                            q[3] = 0x44;
                            r = q + 0x20;
                            q[8] = rand_range(0, 0xFF);
                            *(short *)(q + 0xA) = scale_ticks(0x3C);
                            *(int *)(r + 4) = 2;
                            r[0xA] = col >> 24;
                            r[0xB] = q[0xA];
                        }
                    }
                }
            }
        }
    }
}
